<template>
  <div class="text-secondary">
    <b-col>
      <h5 class="text-left">
        <b>{{ currentCompany.companyName }}</b>
      </h5>
      <hr class="bg-dark mt-1 mb-1" />
      <b-form-group
        label="Nome completo"
        class="mt-0"
        label-for="input-1"
        style="font-weight: bold; font-size: 10pt"
      >
        <b-form-input
          v-model="form.name"
          size="sm"
          type="text"
          placeholder="Nome completo"
          required
        ></b-form-input>
      </b-form-group>

      <b-form-group
        label="Telemóvel"
        label-for="input-2"
        style="font-weight: bold; font-size: 10pt"
      >
        <b-form-input
          v-model="form.phone"
          size="sm"
          placeholder="Digite o telemóvel"
          required
        ></b-form-input>
      </b-form-group>

      <b-form-group
        label="E-mail"
        label-for="input-3"
        style="font-weight: bold; font-size: 10pt"
      >
        <b-form-input
          v-model="form.email"
          type="email"
          size="sm"
          placeholder="Digite o email"
          required
        ></b-form-input>
      </b-form-group>

      <b-form-group
        :label="'Palavra passe: ' + form.password"
        label-for="input-6"
        style="font-weight: bold; font-size: 10pt"
      >
      </b-form-group>

      <b-form-group
        label="Perfil"
        label-for="input-4"
        style="font-weight: bold; font-size: 10pt"
      >
        <b-form-select
          v-model="form.userRole"
          size="sm"
          :options="roles"
          required
        ></b-form-select>
      </b-form-group>

      <b-form-group
        label="Status:"
        label-for="input-5"
        style="font-weight: bold; font-size: 10pt"
      >
        <b-form-select
          v-model="form.status"
          size="sm"
          :options="userStatus"
          required
        ></b-form-select>
      </b-form-group>

      <b-row>
        <b-col lg="6" md="6" sm="12" class="d-flex align-items-center">
          <b-button
            :disabled="isLoading"
            type="button"
            size="sm"
            block
            variant="danger"
            @click="resetFields()"
            ><b-icon icon="trash-fill"></b-icon> &nbsp;Reset</b-button
          >
        </b-col>
        <b-col lg="6" md="6" sm="12" class="d-flex align-items-center">
          <b-button
            :disabled="isLoading"
            type="submit"
            size="sm"
            block
            variant="success"
            @click="registerUser()"
            >Enviar &nbsp;<b-icon icon="telegram"></b-icon
          ></b-button>
        </b-col>
      </b-row>
    </b-col>
  </div>
</template>

<script>
import axios from "axios";
import { mapGetters } from "vuex";
import logs from "@/utils/logs";

export default {
  name: "AddUserComponent",

  data: () => ({
    form: {
      name: "",
      phone: "258",
      email: "",
      password: Math.floor(Math.random() * 1000000) + 1,
      userRole: 1,
      status: 1,
      companyId: "",
    },
    roles: [
      { text: "Atendimento", value: 2 },
      { text: "Gestor de crédito", value: 3 },
      { text: "Admin", value: 1 },
    ],
    userStatus: [
      { text: "Activo", value: 1 },
      { text: "Inactivo", value: 0 },
    ],
  }),

  computed: {
    ...mapGetters(["isLoading", "user", "token", "company", "currentCompany"]),
  },

  methods: {
    registerUser() {
      if (this.form.name.length < 4) {
        this.showToast("Aviso", "warning", "Nome requerido");
        return;
      } else if (this.form.phone.length != 12) {
        this.showToast(
          "Aviso",
          "warning",
          "O número do telemóvel deve conter 12 dígitos."
        );
        return;
      } else {
        this.$store.commit("LOADING_STATUS", true);
        this.form.companyId = this.currentCompany.id;
        const passingValues = this.form;

        axios
          .post("/api/users", passingValues)
          .then((res) => {
            const { success, message } = res.data;
            if (success === true) {
              console.log(res.data);
              this.showToast("Sucesso!", "success", message);
              const logsParams = logs(
                this.user,
                `${passingValues.name} cadastrado com sucesso.`,
                "Cadastro de usuário"
              );
              this.sendUserCredentials(logsParams);
            } else {
              this.showToast("Erro!", "danger", message);
              this.$store.commit("LOADING_STATUS", false);
              this.getUsers();
              this.resetFields();
            }
          })
          .catch((err) => {
            console.log(err);
            this.showToast("Erro!", "danger", err.message);
            this.$store.commit("LOADING_STATUS", false);
          });
      }
    },

    sendUserCredentials(logsParams) {
      this.$store.commit("LOADING_STATUS", true);
      const passingValues = {
        receipient: this.form.phone,
        accountNumber: this.user.id,
        sender: this.currentCompany.smsSender,
        companyId: this.currentCompany.id,
        smsBody: `OTP: ${this.form.password} \n${this.currentCompany.companyName}`,
      };
      this.$store.dispatch("sendSMSMessage", passingValues);
      this.$store.dispatch("addLog", logsParams);
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },

    resetFields() {
      this.form = {
        name: "",
        phone: "258",
        email: "",
        password: Math.floor(Math.random() * 1000000) + 1,
        userRole: 2,
        status: 1,
        companyId: 1,
      };
    },
  },
};
</script>
